-- Restores dictionary entries that the original import left empty (words with no definition).
-- Source: Ho Ngoc Duc, Free Vietnamese Dictionary Project (FVDP) English-Vietnamese dictionary,
-- the same source as the existing vi definitions. Unambiguous source typos are corrected.
-- Idempotent: a word that already has definitions is skipped, a pronunciation is added once.
START TRANSACTION;
-- aluminium
SET @wid := (SELECT id FROM words WHERE word = 'aluminium' AND lang_code = 'en' ORDER BY id LIMIT 1);
SET @restore := @wid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM word_definitions WHERE word_id = @wid);
